 Route::get('/items',function(Request $r){ims_auth($r);return DB::table('items')->whereNull('archived_at')->orderBy('name')->get()->map(fn($i)=>ims_item($i));});
 Route::post('/items',function(Request $r){$u=ims_auth($r);ims_need($u,'items');$d=$r->validate(['sku_id'=>'required|string|max:100','name'=>'required|string|max:255','category'=>'required|string|max:120','unit_price'=>'required|numeric|min:0','abc_class'=>'nullable|in:A,B,C','xyz_class'=>'nullable|in:X,Y,Z','handling_class'=>'nullable|string','lead_time_days'=>'nullable|integer|min:0','shelf_life_days'=>'nullable|integer|min:0','reorder_point'=>'nullable|integer|min:0','supplier_id'=>'nullable|integer']);$id=DB::table('items')->insertGetId($d+['created_by'=>$u->id,'created_at'=>now(),'updated_at'=>now()]);ims_audit($u,'create','item',$id,$d);return response()->json(ims_item(DB::table('items')->find($id)),201);});
 Route::put('/items/{id}',function(Request $r,$id){$u=ims_auth($r);ims_need($u,'items');$i=DB::table('items')->find($id);if(!$i)abort(404,'Item not found.');$d=$r->validate(['name'=>'sometimes|required|string|max:255','category'=>'sometimes|required|string','unit_price'=>'sometimes|required|numeric|min:0','abc_class'=>'sometimes|in:A,B,C','xyz_class'=>'nullable|in:X,Y,Z','handling_class'=>'nullable|string','lead_time_days'=>'sometimes|integer|min:0','shelf_life_days'=>'sometimes|integer|min:0','reorder_point'=>'sometimes|integer|min:0','supplier_id'=>'nullable|integer']);DB::table('items')->where('id',$id)->update($d+['updated_at'=>now()]);ims_audit($u,'update','item',$id,$d);return ims_item(DB::table('items')->find($id));});
