 Route::post('/purchase-orders',function(Request $r){$u=ims_auth($r);ims_need($u,'purchasing');$d=$r->validate(['po_number'=>'required|string|unique:purchase_orders,po_number','supplier_id'=>'required|integer|exists:suppliers,id','lines'=>'required|array|min:1','lines.*.item_id'=>'required|integer|exists:items,id','lines.*.quantity_ordered'=>'required|integer|min:1','lines.*.unit_cost'=>'nullable|numeric|min:0','expected_at'=>'nullable|date','notes'=>'nullable|string']);return DB::transaction(function()use($d,$u){$id=DB::table('purchase_orders')->insertGetId(['po_number'=>$d['po_number'],'supplier_id'=>$d['supplier_id'],'status'=>'ordered','ordered_at'=>today(),'expected_at'=>$d['expected_at']??null,'notes'=>$d['notes']??null,'created_by'=>$u->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['lines'] as $l)DB::table('purchase_order_lines')->insert(['purchase_order_id'=>$id,'item_id'=>$l['item_id'],'quantity_ordered'=>$l['quantity_ordered'],'unit_cost'=>$l['unit_cost']??0,'created_at'=>now(),'updated_at'=>now()]);ims_audit($u,'create','purchase_order',$id,$d);return ['purchase_order'=>DB::table('purchase_orders')->find($id),'lines'=>DB::table('purchase_order_lines')->where('purchase_order_id',$id)->get()];});});
 Route::get('/purchase-orders',function(Request $r){$u=ims_auth($r);ims_need($u,'purchasing');return DB::table('purchase_orders')->orderByDesc('id')->get();});
 Route::post('/purchase-orders/{id}/receive',function(Request $r,$id){$u=ims_auth($r);ims_need($u,'purchasing');$d=$r->validate(['lines'=>'required|array|min:1','lines.*.line_id'=>'required|integer','lines.*.lot_id'=>'required|string','lines.*.quantity'=>'required|integer|min:1','lines.*.received_date'=>'nullable|date','lines.*.expiry_date'=>'nullable|date']);return DB::transaction(function()use($d,$id,$u){$po=DB::table('purchase_orders')->where('id',$id)->lockForUpdate()->first();if(!$po)abort(404,'Purchase order not found.');foreach($d['lines'] as $l){$line=DB::table('purchase_order_lines')->where('id',$l['line_id'])->where('purchase_order_id',$id)->lockForUpdate()->first();if(!$line||$line->quantity_received+$l['quantity']>$line->quantity_ordered)abort(422,'Receipt exceeds ordered quantity.');$item=DB::table('items')->find($line->item_id);$received=$l['received_date']??today()->toDateString();$expiry=$l['expiry_date']??($item->shelf_life_days?date('Y-m-d',strtotime($received.' +'.$item->shelf_life_days.' days')):null);$bid=DB::table('batches')->insertGetId(['lot_id'=>$l['lot_id'],'item_id'=>$item->id,'received_date'=>$received,'expiry_date'=>$expiry,'qty_received'=>$l['quantity'],'qty_remaining'=>$l['quantity'],'status'=>'active','purchase_order_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);DB::table('purchase_order_lines')->where('id',$line->id)->increment('quantity_received',$l['quantity']);DB::table('movements')->insert(['item_id'=>$item->id,'batch_id'=>$bid,'type'=>'received','quantity'=>$l['quantity'],'reason'=>'Received against '.$po->po_number,'actor_id'=>$u->id,'created_at'=>now(),'updated_at'=>now()]);} $pending=DB::table('purchase_order_lines')->where('purchase_order_id',$id)->whereColumn('quantity_received','<','quantity_ordered')->exists();DB::table('purchase_orders')->where('id',$id)->update(['status'=>$pending?'partially_received':'received','updated_at'=>now()]);ims_audit($u,'receive_purchase_order','purchase_order',$id,$d);return ['status'=>$pending?'partially_received':'received'];});});
